mapper.select:
SELECT o.id, o.operate_emp_id, o.operate_time, o.class_name, o.method_name, o.method_params, o.return_value, o.cost_time, e.name AS operateEmpName
FROM operate_log AS o
LEFT JOIN emp AS e
ON o.operate_emp_id = e.id



        e.id = #{operateEmpId}


        AND o.operate_time >= #{beginDate}


        AND o.operate_time <= #{endDate}



ORDER BY o.id DESC
